--##################
--## KEYBINDINGS ###
--##################
-- Port complet depuis Niri (config.kdl binds {})
-- Mod == SUPER. Les équivalents approximatifs sont signalés en commentaire.

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

mainMod = "SUPER"

-- ==============================================================================
-- APPS
-- ==============================================================================
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(terminal .. " -e nvim"))
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh launcher"))
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd("rofi -show drun -theme-str \"window { width: 30%; }\""))
hl.bind(mainMod .. " + ALT + L", hl.dsp.exec_cmd("hyprlock"))

-- Mise à jour complète CachyOS (officiel + AUR + Flatpak + Snap)
hl.bind(mainMod .. " + CTRL + U", hl.dsp.exec_cmd(terminal .. " -e $HOME/.local/bin/cachyos-update"))

-- ==============================================================================
-- PANEL IA (claude / opencode / codex)
-- ==============================================================================
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd(niriScripts .. "/claude_panel.sh"))
hl.bind(mainMod .. " + SHIFT + A", hl.dsp.exec_cmd(niriScripts .. "/claude_panel_pick.sh"))
hl.bind(mainMod .. " + ALT + A", hl.dsp.exec_cmd(niriScripts .. "/claude_panel_bg.sh"))

-- ==============================================================================
-- HUD BLACKARCH & WIDGETS CATALYST (quickshell panels)
-- ==============================================================================
hl.bind(mainMod .. " + Space", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh blackarch"))
hl.bind(mainMod .. " + SHIFT + X", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh blackarch"))

hl.bind(mainMod .. " + Y", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh dashboard"))
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh ai"))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh vm"))
hl.bind(mainMod .. " + S", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh scripts"))
hl.bind(mainMod .. " + G", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh launcher"))
hl.bind(mainMod .. " + SHIFT + T", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh chat"))
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh bots"))
-- Ops : Super+Ctrl+O (Super+Maj+O = vue d'ensemble ; les deux étaient sur la même touche)
hl.bind(mainMod .. " + CTRL + O", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh ops"))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh pkgs"))
hl.bind(mainMod .. " + SHIFT + Comma", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh atelier"))

-- ==============================================================================
-- TERMINAL DÉROULANT
-- ==============================================================================
-- Super + ` : terminal persistant au-dessus de tout (workspace spécial « term »)
hl.bind(mainMod .. " + grave", hl.dsp.workspace.toggle_special("term"))

-- ==============================================================================
-- CLIPBOARD & WALLPAPERS
-- ==============================================================================
hl.bind(mainMod .. " + X", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call panels toggle clip || " .. niriScripts .. "/clipboard-picker.sh"))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd(niriScripts .. "/wallpaper_menu.sh"))
hl.bind(mainMod .. " + ALT + W", hl.dsp.exec_cmd(niriScripts .. "/wallpaper.sh random"))
hl.bind(mainMod .. " + CTRL + Space", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh omarchy"))
hl.bind(mainMod .. " + CTRL + SHIFT + Space", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh omarchy"))
hl.bind(mainMod .. " + ALT + T", hl.dsp.exec_cmd(niriScripts .. "/spell-toggle.sh omarchy"))

-- ==============================================================================
-- CAPTURES D'ÉCRAN (Grim + Slurp)
-- ==============================================================================
-- Super + Shift + S : sélection d'une zone -> sauvegarde + clipboard
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd(niriScripts .. "/quick_shot.sh region"))

-- Print : tout l'écran -> sauvegarde + clipboard
hl.bind("Print", hl.dsp.exec_cmd(niriScripts .. "/quick_shot.sh full"))

-- ==============================================================================
-- SHELL CATALYST, DOCK & SEKAIPOP-RS
-- ==============================================================================
hl.bind(mainMod .. " + ALT + R", hl.dsp.exec_cmd(catalyst .. "/catalyst-session.sh restart"))
hl.bind(mainMod .. " + ALT + D", hl.dsp.exec_cmd("$HOME/.config/dock/launch.sh"))

-- sekaipop-rs (GTK) : réglages / studio IA / layout editor
hl.bind(mainMod .. " + CTRL + S", hl.dsp.exec_cmd("sekaipop-rs --config"))
hl.bind(mainMod .. " + CTRL + A", hl.dsp.exec_cmd("sekaipop-rs --studio"))
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd("sekaipop-rs --editor"))

-- ==============================================================================
-- PANNEAUX AUDIO (here.sh = bon moniteur)
-- ==============================================================================
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd(niriScripts .. "/here.sh -- " .. niriScripts .. "/audio-panel.sh"))
hl.bind(mainMod .. " + ALT + P", hl.dsp.exec_cmd(niriScripts .. "/here.sh -- " .. niriScripts .. "/audio-panel.sh effects"))
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd(niriScripts .. "/here.sh -- " .. niriScripts .. "/audio-return.sh"))

-- ==============================================================================
-- SYSTEM CONTROL (médias, volume, luminosité) — valables sous verrouillage
-- ==============================================================================
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1.5 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call audio mic || wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })
hl.bind(mainMod .. " + CTRL + M", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call audio mic"), { locked = true })
hl.bind(mainMod .. " + ALT + V", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call audio call"))
hl.bind(mainMod .. " + ALT + B", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call panels open sono none"))

hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioStop", hl.dsp.exec_cmd("playerctl stop"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })

hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call brightness up || " .. niriScripts .. "/brightness.sh up"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call brightness down || " .. niriScripts .. "/brightness.sh down"), { locked = true, repeating = true })

-- ==============================================================================
-- INTERFACE & MULTI-FENÊTRES
-- ==============================================================================
-- Overview : hyprexpo (miniatures live) si dispo, sinon panel Quickshell
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd(overview))
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.exec_cmd("qs ipc -p $HOME/.config/quickshell/catalyst call panels toggle overview"))
-- Sélecteur de fenêtres (rofi) conservé sur Alt+Tab
hl.bind("ALT + Tab", hl.dsp.exec_cmd("rofi -show window"))

hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.exit())
hl.bind("CTRL + ALT + Delete", hl.dsp.exit())

-- Win-park (catalyst) : regrouper/masquer les fenêtres
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exec_cmd(catalyst .. "/win-park.sh park"))

-- ==============================================================================
-- FOCUS & DÉPLACEMENT DES FENÊTRES
-- ==============================================================================
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
-- niri : Mod+J/K = focus-window-or-workspace-down/up (approx : focus de fenêtre)
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + Down", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + Up", hl.dsp.focus({ direction = "up" }))

-- niri : move-column-* -> déplacer la fenêtre dans le sens voulu
hl.bind(mainMod .. " + CTRL + Left", hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + CTRL + Right", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + CTRL + H", hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + CTRL + L", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + CTRL + Down", hl.dsp.exec_cmd(dynWs .. " move-next"))
hl.bind(mainMod .. " + CTRL + Up", hl.dsp.exec_cmd(dynWs .. " move-prev"))
hl.bind(mainMod .. " + CTRL + J", hl.dsp.exec_cmd(dynWs .. " move-next"))
hl.bind(mainMod .. " + CTRL + K", hl.dsp.exec_cmd(dynWs .. " move-prev"))

-- Redimensionnement (niri : set-column-width ±10% / set-window-height ±10%)
hl.bind(mainMod .. " + Minus", hl.dsp.window.resize({ x = -80, y = 0, relative = true }), { locked = true, repeating = true })
hl.bind(mainMod .. " + Equal", hl.dsp.window.resize({ x = 80, y = 0, relative = true }), { locked = true, repeating = true })
hl.bind(mainMod .. " + SHIFT + Minus", hl.dsp.window.resize({ x = 0, y = -80, relative = true }), { locked = true, repeating = true })
hl.bind(mainMod .. " + SHIFT + Equal", hl.dsp.window.resize({ x = 0, y = 80, relative = true }), { locked = true, repeating = true })

-- (Pas d'équivalent natif : preset-column-width Mod+R / Mod+Alt+1-4,
--  focus-column-first/last Mod+Home/End, switch-focus-floating Mod+Shift+V)

-- Drag / resize à la souris
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag())
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize())

-- ==============================================================================
-- MONITEURS
-- ==============================================================================
hl.bind(mainMod .. " + ALT + Left", hl.dsp.focus({ monitor = "l" }))
hl.bind(mainMod .. " + ALT + Right", hl.dsp.focus({ monitor = "r" }))
hl.bind(mainMod .. " + ALT + H", hl.dsp.focus({ monitor = "l" }))
-- (" .. mainMod .. " ALT, L = focusmonitor r sous niri, mais entre en conflit avec
--  Super+Alt+L = hyprlock ; Alt+Right couvre déjà ce besoin)
hl.bind(mainMod .. " + ALT + SHIFT + Left", hl.dsp.window.move({ monitor = "l" }))
hl.bind(mainMod .. " + ALT + SHIFT + Right", hl.dsp.window.move({ monitor = "r" }))
hl.bind(mainMod .. " + ALT + SHIFT + H", hl.dsp.window.move({ monitor = "l" }))
hl.bind(mainMod .. " + ALT + SHIFT + L", hl.dsp.window.move({ monitor = "r" }))
-- (move-workspace-to-monitor Mod+Alt+Ctrl+Left/Right : pas d'équivalent direct)

-- ==============================================================================
-- WORKSPACES (dynamiques — dyn-ws.sh, style niri)
-- ==============================================================================
-- Navigation relative par moniteur (crée un nouvel espace au bout de la pile)
hl.bind(mainMod .. " + Left", hl.dsp.exec_cmd(dynWs .. " prev"))
hl.bind(mainMod .. " + Right", hl.dsp.exec_cmd(dynWs .. " next"))
hl.bind(mainMod .. " + U", hl.dsp.exec_cmd(dynWs .. " next"))
hl.bind(mainMod .. " + I", hl.dsp.exec_cmd(dynWs .. " prev"))
hl.bind(mainMod .. " + Page_Down", hl.dsp.exec_cmd(dynWs .. " next"))
hl.bind(mainMod .. " + Page_Up", hl.dsp.exec_cmd(dynWs .. " prev"))

-- Déplacer la fenêtre active d'un espace
hl.bind(mainMod .. " + SHIFT + Left", hl.dsp.exec_cmd(dynWs .. " move-prev"))
hl.bind(mainMod .. " + SHIFT + Right", hl.dsp.exec_cmd(dynWs .. " move-next"))
hl.bind(mainMod .. " + SHIFT + U", hl.dsp.exec_cmd(dynWs .. " move-next"))
hl.bind(mainMod .. " + SHIFT + I", hl.dsp.exec_cmd(dynWs .. " move-prev"))
hl.bind(mainMod .. " + SHIFT + Page_Down", hl.dsp.exec_cmd(dynWs .. " move-next"))
hl.bind(mainMod .. " + SHIFT + Page_Up", hl.dsp.exec_cmd(dynWs .. " move-prev"))

-- Nouvel espace dynamique
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd(dynWs .. " new"))

-- Accès direct (1-9 = Nième espace du moniteur courant)
hl.bind(mainMod .. " + 1", hl.dsp.exec_cmd(dynWs .. " switch 1"))
hl.bind(mainMod .. " + 2", hl.dsp.exec_cmd(dynWs .. " switch 2"))
hl.bind(mainMod .. " + 3", hl.dsp.exec_cmd(dynWs .. " switch 3"))
hl.bind(mainMod .. " + 4", hl.dsp.exec_cmd(dynWs .. " switch 4"))
hl.bind(mainMod .. " + 5", hl.dsp.exec_cmd(dynWs .. " switch 5"))
hl.bind(mainMod .. " + 6", hl.dsp.exec_cmd(dynWs .. " switch 6"))
hl.bind(mainMod .. " + 7", hl.dsp.exec_cmd(dynWs .. " switch 7"))
hl.bind(mainMod .. " + 8", hl.dsp.exec_cmd(dynWs .. " switch 8"))
hl.bind(mainMod .. " + 9", hl.dsp.exec_cmd(dynWs .. " switch 9"))

-- Déplacer la fenêtre active vers un espace
hl.bind(mainMod .. " + CTRL + 1", hl.dsp.exec_cmd(dynWs .. " move 1"))
hl.bind(mainMod .. " + CTRL + 2", hl.dsp.exec_cmd(dynWs .. " move 2"))
hl.bind(mainMod .. " + CTRL + 3", hl.dsp.exec_cmd(dynWs .. " move 3"))
hl.bind(mainMod .. " + CTRL + 4", hl.dsp.exec_cmd(dynWs .. " move 4"))
hl.bind(mainMod .. " + CTRL + 5", hl.dsp.exec_cmd(dynWs .. " move 5"))
hl.bind(mainMod .. " + CTRL + 6", hl.dsp.exec_cmd(dynWs .. " move 6"))
hl.bind(mainMod .. " + CTRL + 7", hl.dsp.exec_cmd(dynWs .. " move 7"))
hl.bind(mainMod .. " + CTRL + 8", hl.dsp.exec_cmd(dynWs .. " move 8"))
hl.bind(mainMod .. " + CTRL + 9", hl.dsp.exec_cmd(dynWs .. " move 9"))

-- ==============================================================================
-- GROUPES (tab groups niri) & GÉOMÉTRIE
-- ==============================================================================
hl.bind(mainMod .. " + W", hl.dsp.group.toggle())
-- (togglesplit n'existe plus sous Hyprland 0.56)
hl.bind(mainMod .. " + Comma", hl.dsp.window.move({ into_or_create_group = "l" }))
hl.bind(mainMod .. " + Period", hl.dsp.window.move({ out_of_group = true }))
hl.bind(mainMod .. " + BracketLeft", hl.dsp.window.move({ into_group = "l" }))
hl.bind(mainMod .. " + BracketRight", hl.dsp.window.move({ into_group = "r" }))

-- ==============================================================================
-- FLOATING, PLEIN ÉCRAN, CENTRAGE
-- ==============================================================================
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
-- niri : maximize-column (Super+F) -> maximiser en gardant les gaps
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
-- niri : fullscreen-window (Super+Shift+F) -> plein écran réel
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
-- niri : center-column
hl.bind(mainMod .. " + C", hl.dsp.window.center())

-- ==============================================================================
-- OUTILS (menus : Informatique · Design · Musique · Divers)
-- ==============================================================================
hl.bind(mainMod .. " + SHIFT + G", hl.dsp.exec_cmd(niriScripts .. "/tools_menu.sh"))
hl.bind(mainMod .. " + ALT + S", hl.dsp.exec_cmd(niriScripts .. "/shot_menu.sh"))
hl.bind(mainMod .. " + ALT + C", hl.dsp.exec_cmd(niriScripts .. "/color_pick.sh"))
hl.bind(mainMod .. " + ALT + M", hl.dsp.exec_cmd(niriScripts .. "/music_menu.sh"))
hl.bind(mainMod .. " + SHIFT + Y", hl.dsp.exec_cmd(niriScripts .. "/translate_sel.sh"))
